// Leave deletes a Member, failing with ErrMemberNotFound if it is absent. It reads the item
// consistently first (not with dynago.From) so it can release what the item contributed, then
// writes everything in one transaction guarded by the item's revision. In the same transaction it
// requires counter MemberLoans to have active = 0 (a missing value counts as 0) (else
// ErrMemberLeaveRequiresMemberLoans). In the same transaction it maintains counter MemberCounts,
// unique claim Email.
//
// Members return everything before they go.
func (s *MemberStore) Leave(ctx context.Context, k MemberKey, opts ...dynago.WriteOption) error {
	key, err := k.dynamoKey()
	if err != nil {
		return err
	}
	o := dynago.ApplyOptions(opts)
	return dynago.Retry(ctx, func() error {
		it, versioned, err := s.start(ctx, key, o, false)
		if err != nil {
			return err
		}
		if it.V > memberVersion {
			return fmt.Errorf("%w: Member at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, memberVersion)
		}
		ops := []dynago.Op{dynago.DeleteOp(key, s.t.Delete("PK", key.PK).Range("SK", key.SK).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", memberVersion), dynago.ErrStale)}
		e := &it.Member
		changes := []dynago.Change{{Owner: key, Before: memberDerived(&it.Member, key, it.V)}}
		// requires MemberLoans
		if e.LibraryID == "" || e.MemberID == "" {
			return fmt.Errorf("%w: Member.Leave requires the MemberLoans, keyed by libraryId and memberId", dynago.ErrFieldRequired)
		}
		memberLoansKey := dynago.Key{PK: "LIB#" + e.LibraryID + "#MEMBER#" + e.MemberID, SK: "LOANS"}
		ops = append(ops, dynago.CheckOp(memberLoansKey, dynago.CheckCounter(s.t, memberLoansKey, []dynago.Cond{{Attr: "active", Value: 0, Zero: true}}), ErrMemberLeaveRequiresMemberLoans))
		derived, err := dynago.DiffAll(s.t, changes)
		if err != nil {
			return err
		}
		ops = append(ops, derived...)
		if err := dynago.Run(ctx, s.db, ops); err != nil {
			return dynago.StaleAs(versioned, err)
		}
		return nil
	})
}

// ---- Tool ----

// ToolCategory is the set of values of Tool.category.
type ToolCategory string

// Values of ToolCategory.
const (
	ToolCategoryPower   ToolCategory = "power"
	ToolCategoryGarden  ToolCategory = "garden"
	ToolCategoryHand    ToolCategory = "hand"
	ToolCategoryKitchen ToolCategory = "kitchen"
	ToolCategoryCamping ToolCategory = "camping"
)

// ToolStatus is the set of values of Tool.status.
type ToolStatus string

// Values of ToolStatus.
const (
	ToolStatusAvailable ToolStatus = "available"
	ToolStatusOnLoan    ToolStatus = "onLoan"
	ToolStatusRetired   ToolStatus = "retired"
)

// Tool is a tool the library lends out.
type Tool struct {
	LibraryID string       `dynamo:"libraryId"`
	ToolID    string       `dynamo:"toolId"`
	Name      string       `dynamo:"name,omitempty"`
	Category  ToolCategory `dynamo:"category,omitempty"`
	Status    ToolStatus   `dynamo:"status,omitempty"`
	// Care and safety notes. Large, so never listed.
	Manual string   `dynamo:"manual,omitempty"`
	Tags   []string `dynamo:"tags,set,omitempty"`
	// The maker's serial number, if it has one.
	SerialNumber string `dynamo:"serialNumber,omitempty"`
	// The library's labels on the tool, scanned at the desk. A tool can carry several (one per part of
	// a kit).
	Barcodes []string  `dynamo:"barcodes,set,omitempty"`
	AddedAt  time.Time `dynamo:"addedAt,omitempty"`

	loaded *toolLoaded // set when the store returns the entity
}

// toolLoaded remembers the stored state an entity was read at, so a write passed the entity
// with dynago.From can start from it without reading again.
type toolLoaded struct {
	rev      int64
	v        int
	snapshot Tool
}

// Version identifies the stored state e was read at, for optimistic concurrency: pass it back
// with dynago.IfVersion (e.g. from an ETag) to make a write fail if anything changed since.
// It is "" for an entity that was not read from the store.
func (e *Tool) Version() string {
	if e.loaded == nil {
		return ""
	}
	return dynago.FormatVersion(e.loaded.rev)
}

// clone copies e, including its slices and maps, without its loaded state.
func (e *Tool) clone() Tool {
	c := *e
	c.loaded = nil
	c.Tags = append([]string(nil), e.Tags...)
	c.Barcodes = append([]string(nil), e.Barcodes...)
	return c
}

// checkKeyParts rejects values containing a character their key templates use as a separator.
func (e *Tool) checkKeyParts() error {
	if err := dynago.CheckKeyPart("libraryId", e.LibraryID, "#"); err != nil {
		return err
	}
	if err := dynago.CheckKeyPart("toolId", e.ToolID, "#"); err != nil {
		return err
	}
	return nil
}

// ToolKey identifies a Tool.
type ToolKey struct {
	LibraryID string
	ToolID    string
}

// Key returns the primary key of e.
func (e *Tool) Key() ToolKey {
	return ToolKey{LibraryID: e.LibraryID, ToolID: e.ToolID}
}

func (k ToolKey) dynamoKey() (dynago.Key, error) {
	if k.LibraryID == "" || k.ToolID == "" {
		return dynago.Key{}, fmt.Errorf("%w: Tool needs libraryId and toolId", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", k.LibraryID, "#"); err != nil {
		return dynago.Key{}, err
	}
	if err := dynago.CheckKeyPart("toolId", k.ToolID, "#"); err != nil {
		return dynago.Key{}, err
	}
	return dynago.Key{PK: "LIB#" + k.LibraryID + "#TOOL#" + k.ToolID, SK: "TOOL"}, nil
}

// Errors returned by ToolStore. Each wraps the matching dynago sentinel.
var (
	ErrToolNotFound           = fmt.Errorf("%w: Tool", dynago.ErrNotFound)
	ErrToolExists             = fmt.Errorf("%w: Tool", dynago.ErrExists)
	ErrToolRetirePrecondition = fmt.Errorf("%w: Tool.Retire requires status = \"available\"", dynago.ErrPrecondition)
	ErrToolSerialTaken        = fmt.Errorf("%w: Tool.Serial", dynago.ErrTaken)
	ErrToolBarcodeTaken       = fmt.Errorf("%w: Tool.Barcode", dynago.ErrTaken)
)

const toolVersion = 2

type toolItem struct {
	Tool
	PK           string `dynamo:"PK"`
	SK           string `dynamo:"SK"`
	T            string `dynamo:"_t"`
	V            int    `dynamo:"_v"`
	Rev          int64  `dynamo:"_rev"`
	ByCategoryPK string `dynamo:"ByCategoryPK,omitempty"`
	ByCategorySK string `dynamo:"ByCategorySK,omitempty"`
}

func toolToItem(e *Tool, key dynago.Key, rev int64) *toolItem {
	it := &toolItem{Tool: *e, PK: key.PK, SK: key.SK, T: "Tool", V: toolVersion, Rev: rev}
	if e.LibraryID != "" && e.Category != "" && e.Name != "" && e.ToolID != "" {
		it.ByCategoryPK = "LIB#" + e.LibraryID + "#CAT#" + string(e.Category)
		it.ByCategorySK = dynago.Lower(e.Name) + "#" + e.ToolID
	}
	return it
}

// ToolByCategory is a Tool as seen through the ByCategory index: key fields plus the projected fields.
type ToolByCategory struct {
	LibraryID string       `dynamo:"libraryId"`
	ToolID    string       `dynamo:"toolId"`
	Name      string       `dynamo:"name,omitempty"`
	Category  ToolCategory `dynamo:"category,omitempty"`
	Status    ToolStatus   `dynamo:"status,omitempty"`
	Tags      []string     `dynamo:"tags,set,omitempty"`
}

// ToolCounts holds the library's catalogue numbers.
type ToolCounts struct {
	// Available counts items where status = "available".
	Available int64 `dynamo:"available"`
	// OnLoan counts items where status = "onLoan".
	OnLoan int64 `dynamo:"onLoan"`
	// Retired counts items where status = "retired".
	Retired int64 `dynamo:"retired"`
}

// ToolCountsKey identifies a ToolCounts counter.
type ToolCountsKey struct {
	LibraryID string
}

// toolDerived returns the counter contributions, claims and copies that exist because of e.
// v is the schema version e was written at: items written before a derived item was
// introduced do not contribute to it.
func toolDerived(e *Tool, owner dynago.Key, v int) []dynago.Derived {
	_ = owner // only sharded counters use it
	var d []dynago.Derived
	// counter ToolCounts
	if e.LibraryID != "" {
		k := dynago.Key{PK: "LIB#" + e.LibraryID, SK: "COUNTS#TOOLS"}
		if e.Status == ToolStatusAvailable {
			d = append(d, dynago.Derived{Kind: dynago.KindCounter, Key: k, Type: "ToolCounts", Attr: "available", Amount: 1})
		}
		if e.Status == ToolStatusOnLoan {
			d = append(d, dynago.Derived{Kind: dynago.KindCounter, Key: k, Type: "ToolCounts", Attr: "onLoan", Amount: 1})
		}
		if e.Status == ToolStatusRetired {
			d = append(d, dynago.Derived{Kind: dynago.KindCounter, Key: k, Type: "ToolCounts", Attr: "retired", Amount: 1})
		}
	}
	// unique Serial
	if e.LibraryID != "" && e.SerialNumber != "" {
		d = append(d, dynago.Derived{Kind: dynago.KindClaim, Key: dynago.Key{PK: "UNIQUE#Tool.Serial#" + e.LibraryID + "#" + e.SerialNumber, SK: "UNIQUE"}, Type: "Tool.Serial", TakenErr: ErrToolSerialTaken})
	}
	// unique Barcode
	if v >= 2 && e.LibraryID != "" {
		for _, elem := range e.Barcodes {
			if elem != "" {
				d = append(d, dynago.Derived{Kind: dynago.KindClaim, Key: dynago.Key{PK: "UNIQUE#Tool.Barcode#" + e.LibraryID + "#" + elem, SK: "UNIQUE"}, Type: "Tool.Barcode", TakenErr: ErrToolBarcodeTaken})
			}
		}
	}
	return d
}

// ToolStore reads and writes Tool items. Only the access patterns declared in the schema
// exist as methods.
type ToolStore struct {
	db *dynamo.DB
	t  dynamo.Table
}

func (s *ToolStore) load(ctx context.Context, key dynago.Key, consistent bool) (*toolItem, error) {
	var raw dynamo.Item
	found, err := dynago.GetOne(ctx, s.t, key, consistent, &raw)
	if err != nil {
		return nil, err
	}
	if !found {
		return nil, ErrToolNotFound
	}
	return toolDecode(raw)
}

// toolDecode decodes a stored item, remembering its state for writes passed dynago.From.
func toolDecode(raw dynamo.Item) (*toolItem, error) {
	var it toolItem
	if err := dynamo.UnmarshalItem(raw, &it); err != nil {
		return nil, err
	}
	it.loaded = &toolLoaded{rev: it.Rev, v: it.V, snapshot: it.clone()}
	return &it, nil
}

func toolDecodeAll(raws []dynamo.Item) ([]Tool, error) {
	out := make([]Tool, 0, len(raws))
	for _, raw := range raws {
		it, err := toolDecode(raw)
		if err != nil {
			return nil, err
		}
		out = append(out, it.Tool)
	}
	return out, nil
}

// from returns the entity passed with dynago.From, checked to be this item and read from the
// store, or nil if none was passed.
func (s *ToolStore) from(key dynago.Key, o dynago.WriteOptions) (*Tool, error) {
	if o.From == nil {
		return nil, nil
	}
	from, ok := o.From.(*Tool)
	if !ok || from == nil || from.loaded == nil {
		return nil, fmt.Errorf("%w: dynago.From needs a *Tool read from its own item, not built by hand or read through a copy index", dynago.ErrVersionRequired)
	}
	if fk, err := from.Key().dynamoKey(); err != nil || fk != key {
		return nil, fmt.Errorf("%w: the Tool passed with dynago.From is a different item", dynago.ErrInvalidKey)
	}
	return from, nil
}

// guard resolves the conditions a single-request write must meet.
func (s *ToolStore) guard(key dynago.Key, o dynago.WriteOptions, required bool) (dynago.Guard, error) {
	expect, err := o.ExpectedRev()
	if err != nil {
		return dynago.Guard{}, err
	}
	from, err := s.from(key, o)
	if err != nil {
		return dynago.Guard{}, err
	}
	if from != nil {
		if expect != 0 && expect != from.loaded.rev {
			return dynago.Guard{}, dynago.ErrVersionMismatch
		}
		expect = from.loaded.rev
	}
	if required && expect == 0 {
		return dynago.Guard{}, dynago.ErrVersionRequired
	}
	return dynago.Guard{ExpectRev: expect, Version: toolVersion, NotFound: ErrToolNotFound}, nil
}

// start returns the state a read-modify-write starts from: the entity passed with dynago.From
// (no read), or a consistent read. versioned reports whether the caller named a version, in
// which case a concurrent change is a mismatch for the caller rather than something to retry.
func (s *ToolStore) start(ctx context.Context, key dynago.Key, o dynago.WriteOptions, required bool) (*toolItem, bool, error) {
	expect, err := o.ExpectedRev()
	if err != nil {
		return nil, false, err
	}
	from, err := s.from(key, o)
	if err != nil {
		return nil, false, err
	}
	if from != nil {
		if expect != 0 && expect != from.loaded.rev {
			return nil, false, dynago.ErrVersionMismatch
		}
		return &toolItem{Tool: from.loaded.snapshot, Rev: from.loaded.rev, V: from.loaded.v}, true, nil
	}
	if required && expect == 0 {
		return nil, false, dynago.ErrVersionRequired
	}
	it, err := s.load(ctx, key, true)
	if err != nil {
		return nil, false, err
	}
	if expect != 0 && it.Rev != expect {
		return nil, false, dynago.ErrVersionMismatch
	}
	return it, expect != 0, nil
}

// Get reads a Tool by primary key with one eventually consistent GetItem.
func (s *ToolStore) Get(ctx context.Context, k ToolKey) (*Tool, error) {
	key, err := k.dynamoKey()
	if err != nil {
		return nil, err
	}
	it, err := s.load(ctx, key, false)
	if err != nil {
		return nil, err
	}
	return &it.Tool, nil
}

// ToolCatalogueQuery selects the partition for Tool.Catalogue.
type ToolCatalogueQuery struct {
	LibraryID string
	Category  ToolCategory
}

// Catalogue returns one page of Tool items from the ByCategory index, ascending by
// "{name|lower}#{toolId}", with exactly one eventually consistent Query (default 25, max 100
// items). It returns the cursor for the next page, or "" at the end.
func (s *ToolStore) Catalogue(ctx context.Context, q ToolCatalogueQuery, page dynago.Page) ([]ToolByCategory, string, error) {
	if q.LibraryID == "" || q.Category == "" {
		return nil, "", fmt.Errorf("%w: Catalogue needs libraryId and category", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", q.LibraryID, "#"); err != nil {
		return nil, "", err
	}
	pk := "LIB#" + q.LibraryID + "#CAT#" + string(q.Category)
	spec := dynago.QuerySpec{Scope: "Tool.Catalogue@v2\x00" + pk, PK: pk, PageSize: 25, MaxPage: 100, Index: "ByCategory", PKAttr: "ByCategoryPK", SKAttr: "ByCategorySK"}
	var out []ToolByCategory
	next, err := dynago.Query(ctx, s.t, spec, page, &out)
	if err != nil {
		return nil, "", err
	}
	return out, next, nil
}

// GetByBarcode finds the Tool holding the given element of barcodes (with libraryId): a consistent
// read of the claim, then of the item.
func (s *ToolStore) GetByBarcode(ctx context.Context, libraryID string, barcodesElem string) (*Tool, error) {
	if libraryID == "" {
		return nil, fmt.Errorf("%w: GetByBarcode needs libraryId", dynago.ErrInvalidKey)
	}
	if barcodesElem == "" {
		return nil, fmt.Errorf("%w: GetByBarcode needs barcodes", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", libraryID, "#"); err != nil {
		return nil, err
	}
	claimKey := dynago.Key{PK: "UNIQUE#Tool.Barcode#" + libraryID + "#" + barcodesElem, SK: "UNIQUE"}
	var claim dynago.Claim
	found, err := dynago.GetOne(ctx, s.t, claimKey, true, &claim)
	if err != nil {
		return nil, err
	}
	if !found {
		return nil, ErrToolNotFound
	}
	it, err := s.load(ctx, dynago.Key{PK: claim.OwnerPK, SK: claim.OwnerSK}, true)
	if err != nil {
		return nil, err
	}
	// The claim is only trusted while the item still holds the value it was taken for.
	held := false
	for _, elem := range it.Barcodes {
		held = held || (dynago.Key{PK: "UNIQUE#Tool.Barcode#" + it.LibraryID + "#" + elem, SK: "UNIQUE"}) == claimKey
	}
	if !held {
		return nil, ErrToolNotFound
	}
	return &it.Tool, nil
}

// Add creates a Tool, failing with ErrToolExists if one already exists. In the same transaction it
// maintains counter ToolCounts, unique claim Serial, unique claim Barcode. Afterwards e.Version()
// returns the new item's version.
func (s *ToolStore) Add(ctx context.Context, e *Tool) error {
	key, err := e.Key().dynamoKey()
	if err != nil {
		return err
	}
	if err := e.checkKeyParts(); err != nil {
		return err
	}
	rev := dynago.NewRev()
	return dynago.Retry(ctx, func() error {
		put := s.t.Put(toolToItem(e, key, rev)).If("attribute_not_exists($)", "PK")
		ops := []dynago.Op{dynago.CreateOp(key, put, ErrToolExists, rev)}
		changes := []dynago.Change{{Owner: key, After: toolDerived(e, key, toolVersion)}}
		derived, err := dynago.DiffAll(s.t, changes)
		if err != nil {
			return err
		}
		ops = append(ops, derived...)
		if err := dynago.Run(ctx, s.db, ops); err != nil {
			return err
		}
		e.loaded = &toolLoaded{rev: rev, v: toolVersion, snapshot: e.clone()}
		return nil
	})
}

// ToolEditDetails holds the new values for Tool.EditDetails.
// Pointer fields are optional: nil leaves the field as it is, a pointer to the zero value clears it.
type ToolEditDetails struct {
	Name   *string
	Manual *string
	Tags   *[]string
}

// EditDetails updates name, manual and tags of a Tool. It reads the item consistently first (not
// with dynago.From) because the change affects the ByCategory index entry, then writes everything
// in one transaction guarded by the item's revision. In the same transaction it maintains counter
// ToolCounts, unique claim Serial, unique claim Barcode. A call that leaves name nil changes
// nothing derived, and runs as a single conditional UpdateItem instead.
func (s *ToolStore) EditDetails(ctx context.Context, k ToolKey, v ToolEditDetails, opts ...dynago.WriteOption) error {
	key, err := k.dynamoKey()
	if err != nil {
		return err
	}
	o := dynago.ApplyOptions(opts)
	if v.Name == nil && v.Manual == nil && v.Tags == nil {
		return nil // nothing to change
	}
	if v.Name == nil {
		// Nothing derived changes: one conditional UpdateItem, no read.
		sets := []dynago.Set{}
		if v.Manual != nil {
			sets = append(sets, dynago.Set{Attr: "manual", Value: *v.Manual, Remove: *v.Manual == ""})
		}
		if v.Tags != nil {
			sets = append(sets, dynago.Set{Attr: "tags", Value: *v.Tags, Remove: len(*v.Tags) == 0, StringSet: true})
		}
		guard, err := s.guard(key, o, true)
		if err != nil {
			return err
		}
		return dynago.Retry(ctx, func() error {
			rev, err := dynago.UpdateFields(ctx, s.t, key, sets, nil, guard, nil)
			if err == nil {
				o.Written(rev)
			}
			return dynago.StaleAs(guard.ExpectRev != 0, err)
		})
	}
	return dynago.Retry(ctx, func() error {
		it, versioned, err := s.start(ctx, key, o, true)
		if err != nil {
			return err
		}
		if it.V > toolVersion {
			return fmt.Errorf("%w: Tool at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, toolVersion)
		}
		before := &it.Tool
		after := before.clone()
		if v.Name != nil {
			after.Name = *v.Name
		}
		if v.Manual != nil {
			after.Manual = *v.Manual
		}
		if v.Tags != nil {
			after.Tags = *v.Tags
		}
		ops := []dynago.Op{dynago.PutOp(key, s.t.Put(toolToItem(&after, key, it.Rev+1)).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", toolVersion), dynago.ErrStale)}
		changes := []dynago.Change{{Owner: key, Before: toolDerived(before, key, it.V), After: toolDerived(&after, key, toolVersion)}}
		derived, err := dynago.DiffAll(s.t, changes)
		if err != nil {
			return err
		}
		ops = append(ops, derived...)
		if err := dynago.Run(ctx, s.db, ops); err != nil {
			return dynago.StaleAs(versioned, err)
		}
		o.Written(it.Rev + 1)
		return nil
	})
}

// ToolRelabel holds the new values for Tool.Relabel.
type ToolRelabel struct {
	Barcodes []string
}

// Relabel updates barcodes of a Tool. It reads the item consistently first (not with dynago.From)
// because the change affects unique claim Barcode, then writes everything in one transaction
// guarded by the item's revision. In the same transaction it maintains counter ToolCounts, unique
// claim Serial, unique claim Barcode.
//
// Replaces the tool's labels: new ones are claimed, dropped ones freed.
func (s *ToolStore) Relabel(ctx context.Context, k ToolKey, v ToolRelabel, opts ...dynago.WriteOption) error {
	key, err := k.dynamoKey()
	if err != nil {
		return err
	}
	o := dynago.ApplyOptions(opts)
	return dynago.Retry(ctx, func() error {
		it, versioned, err := s.start(ctx, key, o, false)
		if err != nil {
			return err
		}
		if it.V > toolVersion {
			return fmt.Errorf("%w: Tool at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, toolVersion)
		}
		before := &it.Tool
		after := before.clone()
		after.Barcodes = v.Barcodes
		ops := []dynago.Op{dynago.PutOp(key, s.t.Put(toolToItem(&after, key, it.Rev+1)).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", toolVersion), dynago.ErrStale)}
		changes := []dynago.Change{{Owner: key, Before: toolDerived(before, key, it.V), After: toolDerived(&after, key, toolVersion)}}
		derived, err := dynago.DiffAll(s.t, changes)
		if err != nil {
			return err
		}
		ops = append(ops, derived...)
		if err := dynago.Run(ctx, s.db, ops); err != nil {
			return dynago.StaleAs(versioned, err)
		}
		o.Written(it.Rev + 1)
		return nil
	})
}

// Retire updates status of a Tool when status = "available" (else ErrToolRetirePrecondition). The
// change to counter ToolCounts is known from the arguments, so it runs without reading the item:
// conditional writes in one transaction. If the item is not in the state assumed, it falls back to
// reading it. In the same transaction it maintains counter ToolCounts, unique claim Serial, unique
// claim Barcode. In the same transaction it deletes the Hold if there is one.
//
// Takes the tool out of the catalogue, cancelling any hold on it.
func (s *ToolStore) Retire(ctx context.Context, k ToolKey, opts ...dynago.WriteOption) error {
	key, err := k.dynamoKey()
	if err != nil {
		return err
	}
	o := dynago.ApplyOptions(opts)
	// The derived changes depend only on the key and the state `when` pins, so try without
	// reading. ReturnVersion and dynago.From need the read path.
	if o.From == nil && o.NewVersion == nil {
		expect, err := o.ExpectedRev()
		if err != nil {
			return err
		}
		err = dynago.Retry(ctx, func() error {
			before := Tool{LibraryID: k.LibraryID, ToolID: k.ToolID, Status: ToolStatusAvailable}
			after := before.clone()
			after.Status = ToolStatusRetired
			sets := []dynago.Set{
				{Attr: "status", Value: ToolStatusRetired},
			}
			u := s.t.Update("PK", key.PK).Range("SK", key.SK)
			dynago.SetFields(u, sets)
			dynago.GuardUpdate(u, dynago.Guard{ExpectRev: expect, Version: toolVersion}, dynago.Now())
			dynago.AtLeastVersion(u, 2)
			for _, c := range []dynago.Cond{{Attr: "status", Value: ToolStatusAvailable, Zero: false}} {
				dynago.CondUpdate(u, c)
			}
			ops := []dynago.Op{dynago.UpdateOp(key, u, dynago.ErrNeedsRead)}
			changes := []dynago.Change{{Owner: key, Before: toolDerived(&before, key, toolVersion), After: toolDerived(&after, key, toolVersion)}}
			// requires Hold
			if after.LibraryID != "" && after.ToolID != "" {
				holdOps, holdChange, err := s.requireRetireHold(ctx, &after, false)
				if err != nil {
					return err
				}
				ops = append(ops, holdOps...)
				changes = append(changes, holdChange)
			}
			derived, err := dynago.DiffAll(s.t, changes)
			if err != nil {
				return err
			}
			ops = append(ops, derived...)
			return dynago.Run(ctx, s.db, ops)
		})
		if !dynago.NeedsRead(err) {
			return err
		}
		// The item was absent, not in the assumed state, or older: the read path reports which.
	}
	return dynago.Retry(ctx, func() error {
		it, versioned, err := s.start(ctx, key, o, false)
		if err != nil {
			return err
		}
		if it.V > toolVersion {
			return fmt.Errorf("%w: Tool at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, toolVersion)
		}
		before := &it.Tool
		if before.Status != ToolStatusAvailable {
			return ErrToolRetirePrecondition
		}
		after := before.clone()
		after.Status = ToolStatusRetired
		ops := []dynago.Op{dynago.PutOp(key, s.t.Put(toolToItem(&after, key, it.Rev+1)).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", toolVersion), dynago.ErrStale)}
		base := ops
		return dynago.StaleAs(versioned, dynago.ReadIfNeeded(func(read bool) error {
			ops := append([]dynago.Op(nil), base...)
			changes := []dynago.Change{{Owner: key, Before: toolDerived(before, key, it.V), After: toolDerived(&after, key, toolVersion)}}
			// requires Hold
			if after.LibraryID != "" && after.ToolID != "" {
				holdOps, holdChange, err := s.requireRetireHold(ctx, &after, read)
				if err != nil {
					return err
				}
				ops = append(ops, holdOps...)
				changes = append(changes, holdChange)
			}
			derived, err := dynago.DiffAll(s.t, changes)
			if err != nil {
				return err
			}
			ops = append(ops, derived...)
			if err := dynago.Run(ctx, s.db, ops); err != nil {
				return err
			}
			o.Written(it.Rev + 1)
			return nil
		}))
	})
}

// requireRetireHold returns the writes Tool.Retire makes to the Hold: it deletes the Hold if there
// is one. Unless read is set, it assumes that state without reading the Hold: if the assumption is
// wrong, the transaction fails with dynago.ErrNeedsRead and the caller runs again with read set.
func (s *ToolStore) requireRetireHold(ctx context.Context, e *Tool, read bool) ([]dynago.Op, dynago.Change, error) {
	k := HoldKey{LibraryID: e.LibraryID, ToolID: e.ToolID}
	key, err := k.dynamoKey()
	if err != nil {
		return nil, dynago.Change{}, err
	}
	if !read {
		req := dynago.Requirement{Key: key, TTLAttr: "ttl", Optional: true}
		return []dynago.Op{dynago.DeleteOp(key, dynago.ConsumeRequirement(s.t, req, holdVersion), dynago.ErrNeedsRead)}, dynago.Change{}, nil
	}
	it, err := (&HoldStore{db: s.db, t: s.t}).load(ctx, key, true)
	if err == ErrHoldNotFound {
		// Nothing to change, as long as one doesn't appear before the write commits.
		return []dynago.Op{dynago.CheckOp(key, dynago.CheckAbsent(s.t, key, "ttl"), dynago.ErrStale)}, dynago.Change{}, nil
	}
	if err != nil {
		return nil, dynago.Change{}, err
	}
	if it.V > holdVersion {
		return nil, dynago.Change{}, fmt.Errorf("%w: Hold at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, holdVersion)
	}
	return []dynago.Op{dynago.DeleteOp(key, s.t.Delete("PK", key.PK).Range("SK", key.SK).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", holdVersion), dynago.ErrStale)}, dynago.Change{}, nil
}

// ---- Loan ----

// LoanStatus is the set of values of Loan.status.
type LoanStatus string

// Values of LoanStatus.
const (
	LoanStatusActive   LoanStatus = "active"
	LoanStatusReturned LoanStatus = "returned"
)

// Loan is a member borrowing a tool.
type Loan struct {
	LibraryID string `dynamo:"libraryId"`
	ToolID    string `dynamo:"toolId"`
	// A ULID, so a tool's loans sort by time.
	LoanID   string `dynamo:"loanId"`
	MemberID string `dynamo:"memberId,omitempty"`
	// Shown in "my loans" without reading the tool.
	ToolName string `dynamo:"toolName,omitempty"`
	// Set by Borrow and Return; callers never choose it.
	Status     LoanStatus `dynamo:"status,omitempty"`
	BorrowedAt time.Time  `dynamo:"borrowedAt,omitempty"`
	DueAt      time.Time  `dynamo:"dueAt,omitempty"`
	ReturnedAt time.Time  `dynamo:"returnedAt,omitempty"`
	// Condition notes from the steward. Not listed.
	Notes string `dynamo:"notes,omitempty"`

	loaded *loanLoaded // set when the store returns the entity
}

// loanLoaded remembers the stored state an entity was read at, so a write passed the entity
// with dynago.From can start from it without reading again.
type loanLoaded struct {
	rev      int64
	v        int
	snapshot Loan
}

// Version identifies the stored state e was read at, for optimistic concurrency: pass it back
// with dynago.IfVersion (e.g. from an ETag) to make a write fail if anything changed since.
// It is "" for an entity that was not read from the store.
func (e *Loan) Version() string {
	if e.loaded == nil {
		return ""
	}
	return dynago.FormatVersion(e.loaded.rev)
}

// clone copies e, including its slices and maps, without its loaded state.
func (e *Loan) clone() Loan {
	c := *e
	c.loaded = nil
	return c
}

// checkKeyParts rejects values containing a character their key templates use as a separator.
func (e *Loan) checkKeyParts() error {
	if err := dynago.CheckKeyPart("libraryId", e.LibraryID, "#"); err != nil {
		return err
	}
	if err := dynago.CheckKeyPart("toolId", e.ToolID, "#"); err != nil {
		return err
	}
	return nil
}

// LoanKey identifies a Loan.
type LoanKey struct {
	LibraryID string
	ToolID    string
	LoanID    string
}

// Key returns the primary key of e.
func (e *Loan) Key() LoanKey {
	return LoanKey{LibraryID: e.LibraryID, ToolID: e.ToolID, LoanID: e.LoanID}
}

func (k LoanKey) dynamoKey() (dynago.Key, error) {
	if k.LibraryID == "" || k.ToolID == "" || k.LoanID == "" {
		return dynago.Key{}, fmt.Errorf("%w: Loan needs libraryId, toolId and loanId", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", k.LibraryID, "#"); err != nil {
		return dynago.Key{}, err
	}
	if err := dynago.CheckKeyPart("toolId", k.ToolID, "#"); err != nil {
		return dynago.Key{}, err
	}
	return dynago.Key{PK: "LIB#" + k.LibraryID + "#TOOL#" + k.ToolID, SK: "LOAN#" + k.LoanID}, nil
}

// Errors returned by LoanStore. Each wraps the matching dynago sentinel.
var (
	ErrLoanNotFound             = fmt.Errorf("%w: Loan", dynago.ErrNotFound)
	ErrLoanExists               = fmt.Errorf("%w: Loan", dynago.ErrExists)
	ErrLoanReturnPrecondition   = fmt.Errorf("%w: Loan.Return requires status = \"active\"", dynago.ErrPrecondition)
	ErrLoanExtendPrecondition   = fmt.Errorf("%w: Loan.Extend requires status = \"active\"", dynago.ErrPrecondition)
	ErrLoanBorrowRequiresMember = fmt.Errorf("%w: Loan.Borrow requires the Member to exist with status = \"active\"", dynago.ErrPrecondition)
	ErrLoanBorrowRequiresTool   = fmt.Errorf("%w: Loan.Borrow requires the Tool to exist with status = \"available\"", dynago.ErrPrecondition)
	ErrLoanBorrowRequiresHold   = fmt.Errorf("%w: Loan.Borrow requires any Hold to have memberId = Loan.memberId (an absent or expired one passes)", dynago.ErrPrecondition)
	ErrLoanReturnRequiresTool   = fmt.Errorf("%w: Loan.Return requires the Tool to exist with status = \"onLoan\"", dynago.ErrPrecondition)
	ErrMemberLoansActiveLimit   = fmt.Errorf("%w: MemberLoans.active", dynago.ErrLimit)
)

const loanVersion = 1

type loanItem struct {
	Loan
	PK        string `dynamo:"PK"`
	SK        string `dynamo:"SK"`
	T         string `dynamo:"_t"`
	V         int    `dynamo:"_v"`
	Rev       int64  `dynamo:"_rev"`
	OverduePK string `dynamo:"OverduePK,omitempty"`
	OverdueSK string `dynamo:"OverdueSK,omitempty"`
}

func loanToItem(e *Loan, key dynago.Key, rev int64) *loanItem {
	it := &loanItem{Loan: *e, PK: key.PK, SK: key.SK, T: "Loan", V: loanVersion, Rev: rev}
	if e.LibraryID != "" && !e.DueAt.IsZero() && e.LoanID != "" && e.Status == LoanStatusActive {
		it.OverduePK = "LIB#" + e.LibraryID + "#DUE"
		it.OverdueSK = dynago.FmtTime(e.DueAt) + "#" + e.LoanID
	}
	return it
}

// LoanByMember is a Loan as seen through the ByMember index: key fields plus the projected fields.
type LoanByMember struct {
	LibraryID string    `dynamo:"libraryId"`
	ToolID    string    `dynamo:"toolId"`
	LoanID    string    `dynamo:"loanId"`
	MemberID  string    `dynamo:"memberId,omitempty"`
	ToolName  string    `dynamo:"toolName,omitempty"`
	DueAt     time.Time `dynamo:"dueAt,omitempty"`
}

type loanByMemberCopy struct {
	LoanByMember
	PK string `dynamo:"PK"`
	SK string `dynamo:"SK"`
	T  string `dynamo:"_t"`
	V  int    `dynamo:"_v"`
}

// LoanOverdue is a Loan as seen through the Overdue index: key fields plus the projected fields.
type LoanOverdue struct {
	LibraryID string    `dynamo:"libraryId"`
	ToolID    string    `dynamo:"toolId"`
	LoanID    string    `dynamo:"loanId"`
	MemberID  string    `dynamo:"memberId,omitempty"`
	ToolName  string    `dynamo:"toolName,omitempty"`
	DueAt     time.Time `dynamo:"dueAt,omitempty"`
}

// MemberLoans counts each member's loans.
type MemberLoans struct {
	// Active counts items where status = "active"; writes that grow it take a caller-supplied limit.
	Active int64 `dynamo:"active"`
}

// MemberLoansKey identifies a MemberLoans counter.
type MemberLoansKey struct {
	LibraryID string
	MemberID  string
}

// LoanTotals counts every loan the library has made. Sharded to show how: a counter that every
// write of a busy entity touches can take ~1,000 writes/s per shard. This library's rate needs one
// item.
type LoanTotals struct {
	// Started counts items.
	Started int64 `dynamo:"started"`
}

// LoanTotalsKey identifies a LoanTotals counter.
type LoanTotalsKey struct {
	LibraryID string
}

type loanLimits struct {
	MemberLoansActive dynago.Limit
}

// LoanBorrowLimits caps the counters Loan.Borrow can grow. Give every field, as dynago.Max(n) or
// dynago.Unlimited(): a missing limit fails the write with dynago.ErrLimitRequired.
type LoanBorrowLimits struct {
	MemberLoansActive dynago.Limit
}

// loanDerived returns the counter contributions, claims and copies that exist because of e.
// v is the schema version e was written at: items written before a derived item was
// introduced do not contribute to it.
func loanDerived(e *Loan, owner dynago.Key, v int, lim loanLimits) []dynago.Derived {
	var d []dynago.Derived
	// counter MemberLoans
	if e.LibraryID != "" && e.MemberID != "" {
		k := dynago.Key{PK: "LIB#" + e.LibraryID + "#MEMBER#" + e.MemberID, SK: "LOANS"}
		if e.Status == LoanStatusActive {
			d = append(d, dynago.Derived{Kind: dynago.KindCounter, Key: k, Type: "MemberLoans", Attr: "active", Amount: 1, Limit: lim.MemberLoansActive, LimitErr: ErrMemberLoansActiveLimit, LimitRequired: true})
		}
	}
	// counter LoanTotals
	if e.LibraryID != "" {
		k := dynago.Key{PK: dynago.ShardPK("LIB#"+e.LibraryID+"#LOANTOTALS", owner, 4), SK: "TOTALS"}
		d = append(d, dynago.Derived{Kind: dynago.KindCounter, Key: k, Type: "LoanTotals", Attr: "started", Amount: 1})
	}
	// copy index ByMember
	if e.LibraryID != "" && e.MemberID != "" && !e.DueAt.IsZero() && e.ToolID != "" && e.LoanID != "" && e.Status == LoanStatusActive {
		k := dynago.Key{PK: "LIB#" + e.LibraryID + "#MEMBER#" + e.MemberID, SK: "MYLOAN#" + dynago.FmtTime(e.DueAt) + "#" + e.ToolID + "#" + e.LoanID}
		d = append(d, dynago.Derived{Kind: dynago.KindCopy, Key: k, Type: "Loan.ByMember", Item: &loanByMemberCopy{LoanByMember: LoanByMember{LibraryID: e.LibraryID, ToolID: e.ToolID, LoanID: e.LoanID, MemberID: e.MemberID, ToolName: e.ToolName, DueAt: e.DueAt}, PK: k.PK, SK: k.SK, T: "Loan.ByMember", V: loanVersion}})
	}
	return d
}

// LoanStore reads and writes Loan items. Only the access patterns declared in the schema
// exist as methods.
type LoanStore struct {
	db *dynamo.DB
	t  dynamo.Table
}

func (s *LoanStore) load(ctx context.Context, key dynago.Key, consistent bool) (*loanItem, error) {
	var raw dynamo.Item
	found, err := dynago.GetOne(ctx, s.t, key, consistent, &raw)
	if err != nil {
		return nil, err
	}
	if !found {
		return nil, ErrLoanNotFound
	}
	return loanDecode(raw)
}

// loanDecode decodes a stored item, remembering its state for writes passed dynago.From.
func loanDecode(raw dynamo.Item) (*loanItem, error) {
	var it loanItem
	if err := dynamo.UnmarshalItem(raw, &it); err != nil {
		return nil, err
	}
	it.loaded = &loanLoaded{rev: it.Rev, v: it.V, snapshot: it.clone()}
	return &it, nil
}

func loanDecodeAll(raws []dynamo.Item) ([]Loan, error) {
	out := make([]Loan, 0, len(raws))
	for _, raw := range raws {
		it, err := loanDecode(raw)
		if err != nil {
			return nil, err
		}
		out = append(out, it.Loan)
	}
	return out, nil
}

// from returns the entity passed with dynago.From, checked to be this item and read from the
// store, or nil if none was passed.
func (s *LoanStore) from(key dynago.Key, o dynago.WriteOptions) (*Loan, error) {
	if o.From == nil {
		return nil, nil
	}
	from, ok := o.From.(*Loan)
	if !ok || from == nil || from.loaded == nil {
		return nil, fmt.Errorf("%w: dynago.From needs a *Loan read from its own item, not built by hand or read through a copy index", dynago.ErrVersionRequired)
	}
	if fk, err := from.Key().dynamoKey(); err != nil || fk != key {
		return nil, fmt.Errorf("%w: the Loan passed with dynago.From is a different item", dynago.ErrInvalidKey)
	}
	return from, nil
}

// guard resolves the conditions a single-request write must meet.
func (s *LoanStore) guard(key dynago.Key, o dynago.WriteOptions, required bool) (dynago.Guard, error) {
	expect, err := o.ExpectedRev()
	if err != nil {
		return dynago.Guard{}, err
	}
	from, err := s.from(key, o)
	if err != nil {
		return dynago.Guard{}, err
	}
	if from != nil {
		if expect != 0 && expect != from.loaded.rev {
			return dynago.Guard{}, dynago.ErrVersionMismatch
		}
		expect = from.loaded.rev
	}
	if required && expect == 0 {
		return dynago.Guard{}, dynago.ErrVersionRequired
	}
	return dynago.Guard{ExpectRev: expect, Version: loanVersion, NotFound: ErrLoanNotFound}, nil
}

// start returns the state a read-modify-write starts from: the entity passed with dynago.From
// (no read), or a consistent read. versioned reports whether the caller named a version, in
// which case a concurrent change is a mismatch for the caller rather than something to retry.
func (s *LoanStore) start(ctx context.Context, key dynago.Key, o dynago.WriteOptions, required bool) (*loanItem, bool, error) {
	expect, err := o.ExpectedRev()
	if err != nil {
		return nil, false, err
	}
	from, err := s.from(key, o)
	if err != nil {
		return nil, false, err
	}
	if from != nil {
		if expect != 0 && expect != from.loaded.rev {
			return nil, false, dynago.ErrVersionMismatch
		}
		return &loanItem{Loan: from.loaded.snapshot, Rev: from.loaded.rev, V: from.loaded.v}, true, nil
	}
	if required && expect == 0 {
		return nil, false, dynago.ErrVersionRequired
	}
	it, err := s.load(ctx, key, true)
	if err != nil {
		return nil, false, err
	}
	if expect != 0 && it.Rev != expect {
		return nil, false, dynago.ErrVersionMismatch
	}
	return it, expect != 0, nil
}

// Get reads a Loan by primary key with one eventually consistent GetItem.
func (s *LoanStore) Get(ctx context.Context, k LoanKey) (*Loan, error) {
	key, err := k.dynamoKey()
	if err != nil {
		return nil, err
	}
	it, err := s.load(ctx, key, false)
	if err != nil {
		return nil, err
	}
	return &it.Loan, nil
}

// LoanHistoryItem is what Loan.History returns: the key fields plus memberId, status, borrowedAt, dueAt and returnedAt.
type LoanHistoryItem struct {
	LibraryID  string     `dynamo:"libraryId"`
	ToolID     string     `dynamo:"toolId"`
	LoanID     string     `dynamo:"loanId"`
	MemberID   string     `dynamo:"memberId,omitempty"`
	Status     LoanStatus `dynamo:"status,omitempty"`
	BorrowedAt time.Time  `dynamo:"borrowedAt,omitempty"`
	DueAt      time.Time  `dynamo:"dueAt,omitempty"`
	ReturnedAt time.Time  `dynamo:"returnedAt,omitempty"`
}

// LoanHistoryQuery selects the partition for Loan.History.
type LoanHistoryQuery struct {
	LibraryID string
	ToolID    string
}

// History returns one page of Loan items from the table, descending by "LOAN#{loanId}", with
// exactly one eventually consistent Query (default 20, max 100 items). It returns the cursor for
// the next page, or "" at the end.
//
// A tool's loans, newest first, without the notes.
func (s *LoanStore) History(ctx context.Context, q LoanHistoryQuery, page dynago.Page) ([]LoanHistoryItem, string, error) {
	if q.LibraryID == "" || q.ToolID == "" {
		return nil, "", fmt.Errorf("%w: History needs libraryId and toolId", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", q.LibraryID, "#"); err != nil {
		return nil, "", err
	}
	if err := dynago.CheckKeyPart("toolId", q.ToolID, "#"); err != nil {
		return nil, "", err
	}
	pk := "LIB#" + q.LibraryID + "#TOOL#" + q.ToolID
	spec := dynago.QuerySpec{Scope: "Loan.History@v1\x00" + pk, PK: pk, PageSize: 20, MaxPage: 100, PKAttr: "PK", SKAttr: "SK", Prefix: "LOAN#", Desc: true, Project: []string{"libraryId", "toolId", "loanId", "memberId", "status", "borrowedAt", "dueAt", "returnedAt"}}
	var out []LoanHistoryItem
	next, err := dynago.Query(ctx, s.t, spec, page, &out)
	if err != nil {
		return nil, "", err
	}
	return out, next, nil
}

// LoanMyLoansQuery selects the partition for Loan.MyLoans.
type LoanMyLoansQuery struct {
	LibraryID string
	MemberID  string
}

// MyLoans returns one page of Loan items from the ByMember copy items, ascending by
// "MYLOAN#{dueAt}#{toolId}#{loanId}", with exactly one strongly consistent Query (default 50, max
// 100 items). It returns the cursor for the next page, or "" at the end.
//
// A member's current loans, soonest due first.
func (s *LoanStore) MyLoans(ctx context.Context, q LoanMyLoansQuery, page dynago.Page) ([]LoanByMember, string, error) {
	if q.LibraryID == "" || q.MemberID == "" {
		return nil, "", fmt.Errorf("%w: MyLoans needs libraryId and memberId", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", q.LibraryID, "#"); err != nil {
		return nil, "", err
	}
	pk := "LIB#" + q.LibraryID + "#MEMBER#" + q.MemberID
	spec := dynago.QuerySpec{Scope: "Loan.MyLoans@v1\x00" + pk, PK: pk, PageSize: 50, MaxPage: 100, PKAttr: "PK", SKAttr: "SK", Prefix: "MYLOAN#", Consistent: true}
	var out []LoanByMember
	next, err := dynago.Query(ctx, s.t, spec, page, &out)
	if err != nil {
		return nil, "", err
	}
	return out, next, nil
}

// LoanOverdueQuery selects the partition for Loan.Overdue.
type LoanOverdueQuery struct {
	LibraryID string
	// From and To bound dueAt inclusively; nil leaves that end open.
	From, To *time.Time
}

// Overdue returns one page of Loan items from the Overdue index, ascending by "{dueAt}#{loanId}",
// with exactly one eventually consistent Query (default 50, max 100 items). It returns the cursor
// for the next page, or "" at the end.
func (s *LoanStore) Overdue(ctx context.Context, q LoanOverdueQuery, page dynago.Page) ([]LoanOverdue, string, error) {
	if q.LibraryID == "" {
		return nil, "", fmt.Errorf("%w: Overdue needs libraryId", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", q.LibraryID, "#"); err != nil {
		return nil, "", err
	}
	pk := "LIB#" + q.LibraryID + "#DUE"
	spec := dynago.QuerySpec{Scope: "Loan.Overdue@v1\x00" + pk, PK: pk, PageSize: 50, MaxPage: 100, Index: "Overdue", PKAttr: "OverduePK", SKAttr: "OverdueSK"}
	if q.From != nil {
		from := dynago.FmtTime(*q.From)
		spec.From = &from
	}
	if q.To != nil {
		to := dynago.FmtTime(*q.To)
		spec.To = &to
	}
	var out []LoanOverdue
	next, err := dynago.Query(ctx, s.t, spec, page, &out)
	if err != nil {
		return nil, "", err
	}
	return out, next, nil
}

// ActiveLoans reads the MemberLoans counter (one eventually consistent GetItem). A counter nothing
// has touched reads as zero.
func (s *LoanStore) ActiveLoans(ctx context.Context, k MemberLoansKey) (MemberLoans, error) {
	if k.LibraryID == "" || k.MemberID == "" {
		return MemberLoans{}, fmt.Errorf("%w: MemberLoans needs libraryId and memberId", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", k.LibraryID, "#"); err != nil {
		return MemberLoans{}, err
	}
	var out MemberLoans
	_, err := dynago.GetOne(ctx, s.t, dynago.Key{PK: "LIB#" + k.LibraryID + "#MEMBER#" + k.MemberID, SK: "LOANS"}, false, &out)
	return out, err
}

// Totals reads the LoanTotals counter (one eventually consistent BatchGetItem over 4 shards). A
// counter nothing has touched reads as zero.
func (s *LoanStore) Totals(ctx context.Context, k LoanTotalsKey) (LoanTotals, error) {
	if k.LibraryID == "" {
		return LoanTotals{}, fmt.Errorf("%w: LoanTotals needs libraryId", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", k.LibraryID, "#"); err != nil {
		return LoanTotals{}, err
	}
	sk := "TOTALS"
	var keys []dynago.Key
	for _, pk := range dynago.ShardPKs("LIB#"+k.LibraryID+"#LOANTOTALS", 4) {
		keys = append(keys, dynago.Key{PK: pk, SK: sk})
	}
	var parts []LoanTotals
	if err := dynago.GetMany(ctx, s.t, keys, false, &parts); err != nil {
		return LoanTotals{}, err
	}
	var out LoanTotals
	for _, p := range parts {
		out.Started += p.Started
	}
	return out, nil
}

// Borrow creates a Loan, failing with ErrLoanExists if one already exists. It sets status to
// "active", whatever e holds. MemberId, borrowedAt and dueAt must be set (else
// dynago.ErrFieldRequired). In the same transaction it requires the Member to exist with status =
// "active" (else ErrLoanBorrowRequiresMember); the Tool to exist with status = "available" (else
// ErrLoanBorrowRequiresTool), and sets its status to "onLoan"; any Hold to have memberId =
// Loan.memberId (an absent or expired one passes) (else ErrLoanBorrowRequiresHold), and deletes the
// Hold if there is one. In the same transaction it maintains counter MemberLoans, counter
// LoanTotals, copy index ByMember. Afterwards e.Version() returns the new item's version.
func (s *LoanStore) Borrow(ctx context.Context, e *Loan, limits LoanBorrowLimits) error {
	e.Status = LoanStatusActive
	key, err := e.Key().dynamoKey()
	if err != nil {
		return err
	}
	if err := dynago.RequireLimit("LoanBorrowLimits.MemberLoansActive", limits.MemberLoansActive); err != nil {
		return err
	}
	if e.MemberID == "" {
		err := fmt.Errorf("%w: Loan.memberId", dynago.ErrFieldRequired)
		return err
	}
	if e.BorrowedAt.IsZero() {
		err := fmt.Errorf("%w: Loan.borrowedAt", dynago.ErrFieldRequired)
		return err
	}
	if e.DueAt.IsZero() {
		err := fmt.Errorf("%w: Loan.dueAt", dynago.ErrFieldRequired)
		return err
	}
	if err := e.checkKeyParts(); err != nil {
		return err
	}
	rev := dynago.NewRev()
	return dynago.Retry(ctx, func() error {
		err := dynago.ReadIfNeeded(func(read bool) error {
			put := s.t.Put(loanToItem(e, key, rev)).If("attribute_not_exists($)", "PK")
			ops := []dynago.Op{dynago.CreateOp(key, put, ErrLoanExists, rev)}
			changes := []dynago.Change{{Owner: key, After: loanDerived(e, key, loanVersion, loanLimits{MemberLoansActive: limits.MemberLoansActive})}}
			// requires Member
			if e.LibraryID == "" || e.MemberID == "" {
				return fmt.Errorf("%w: Loan.Borrow requires the Member, keyed by libraryId and memberId", dynago.ErrFieldRequired)
			}
			memberKey := dynago.Key{PK: "LIB#" + e.LibraryID, SK: "MEMBER#" + e.MemberID}
			ops = append(ops, dynago.CheckOp(memberKey, dynago.CheckRequirement(s.t, dynago.Requirement{Key: memberKey, When: []dynago.Cond{{Attr: "status", Value: MemberStatusActive, Zero: false}}}), ErrLoanBorrowRequiresMember))
			// requires Tool
			if e.LibraryID == "" || e.ToolID == "" {
				return fmt.Errorf("%w: Loan.Borrow requires the Tool, keyed by libraryId and toolId", dynago.ErrFieldRequired)
			}
			toolOps, toolChange, err := s.requireBorrowTool(ctx, e, read)
			if err != nil {
				return err
			}
			ops = append(ops, toolOps...)
			changes = append(changes, toolChange)
			// requires Hold
			if e.LibraryID != "" && e.ToolID != "" {
				holdOps, holdChange, err := s.requireBorrowHold(ctx, e, read)
				if err != nil {
					return err
				}
				ops = append(ops, holdOps...)
				changes = append(changes, holdChange)
			}
			derived, err := dynago.DiffAll(s.t, changes)
			if err != nil {
				return err
			}
			ops = append(ops, derived...)
			return dynago.Run(ctx, s.db, ops)
		})
		if err != nil {
			return err
		}
		e.loaded = &loanLoaded{rev: rev, v: loanVersion, snapshot: e.clone()}
		return nil
	})
}

// LoanReturn holds the new values for Loan.Return.
type LoanReturn struct {
	ReturnedAt time.Time
}

// Return updates returnedAt and status of a Loan when status = "active" (else
// ErrLoanReturnPrecondition). It reads the item consistently first (not with dynago.From) because
// the change affects the ByMember index entry, the Overdue index entry, counter MemberLoans, then
// writes everything in one transaction guarded by the item's revision. In the same transaction it
// maintains counter MemberLoans, counter LoanTotals, copy index ByMember. In the same transaction
// it requires the Tool to exist with status = "onLoan" (else ErrLoanReturnRequiresTool), and sets
// its status to "available".
func (s *LoanStore) Return(ctx context.Context, k LoanKey, v LoanReturn, opts ...dynago.WriteOption) error {
	key, err := k.dynamoKey()
	if err != nil {
		return err
	}
	o := dynago.ApplyOptions(opts)
	return dynago.Retry(ctx, func() error {
		it, versioned, err := s.start(ctx, key, o, false)
		if err != nil {
			return err
		}
		if it.V > loanVersion {
			return fmt.Errorf("%w: Loan at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, loanVersion)
		}
		before := &it.Loan
		if before.Status != LoanStatusActive {
			return ErrLoanReturnPrecondition
		}
		after := before.clone()
		after.ReturnedAt = v.ReturnedAt
		after.Status = LoanStatusReturned
		ops := []dynago.Op{dynago.PutOp(key, s.t.Put(loanToItem(&after, key, it.Rev+1)).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", loanVersion), dynago.ErrStale)}
		base := ops
		return dynago.StaleAs(versioned, dynago.ReadIfNeeded(func(read bool) error {
			ops := append([]dynago.Op(nil), base...)
			changes := []dynago.Change{{Owner: key, Before: loanDerived(before, key, it.V, loanLimits{}), After: loanDerived(&after, key, loanVersion, loanLimits{})}}
			// requires Tool
			if after.LibraryID == "" || after.ToolID == "" {
				return fmt.Errorf("%w: Loan.Return requires the Tool, keyed by libraryId and toolId", dynago.ErrFieldRequired)
			}
			toolOps, toolChange, err := s.requireReturnTool(ctx, &after, read)
			if err != nil {
				return err
			}
			ops = append(ops, toolOps...)
			changes = append(changes, toolChange)
			derived, err := dynago.DiffAll(s.t, changes)
			if err != nil {
				return err
			}
			ops = append(ops, derived...)
			if err := dynago.Run(ctx, s.db, ops); err != nil {
				return err
			}
			o.Written(it.Rev + 1)
			return nil
		}))
	})
}

// LoanExtend holds the new values for Loan.Extend.
type LoanExtend struct {
	DueAt time.Time
}

// Extend updates dueAt of a Loan when status = "active" (else ErrLoanExtendPrecondition). It reads
// the item consistently first (not with dynago.From) because the change affects the ByMember index
// entry, the Overdue index entry, then writes everything in one transaction guarded by the item's
// revision. In the same transaction it maintains counter MemberLoans, counter LoanTotals, copy
// index ByMember. DueAt may not be set to the zero value (dynago.ErrFieldRequired).
func (s *LoanStore) Extend(ctx context.Context, k LoanKey, v LoanExtend, opts ...dynago.WriteOption) error {
	key, err := k.dynamoKey()
	if err != nil {
		return err
	}
	if v.DueAt.IsZero() {
		err := fmt.Errorf("%w: Loan.dueAt", dynago.ErrFieldRequired)
		return err
	}
	o := dynago.ApplyOptions(opts)
	return dynago.Retry(ctx, func() error {
		it, versioned, err := s.start(ctx, key, o, false)
		if err != nil {
			return err
		}
		if it.V > loanVersion {
			return fmt.Errorf("%w: Loan at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, loanVersion)
		}
		before := &it.Loan
		if before.Status != LoanStatusActive {
			return ErrLoanExtendPrecondition
		}
		after := before.clone()
		after.DueAt = v.DueAt
		ops := []dynago.Op{dynago.PutOp(key, s.t.Put(loanToItem(&after, key, it.Rev+1)).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", loanVersion), dynago.ErrStale)}
		changes := []dynago.Change{{Owner: key, Before: loanDerived(before, key, it.V, loanLimits{}), After: loanDerived(&after, key, loanVersion, loanLimits{})}}
		derived, err := dynago.DiffAll(s.t, changes)
		if err != nil {
			return err
		}
		ops = append(ops, derived...)
		if err := dynago.Run(ctx, s.db, ops); err != nil {
			return dynago.StaleAs(versioned, err)
		}
		o.Written(it.Rev + 1)
		return nil
	})
}

// LoanAddNote holds the new values for Loan.AddNote.
// Pointer fields are optional: nil leaves the field as it is, a pointer to the zero value clears it.
type LoanAddNote struct {
	Notes *string
}

// AddNote updates notes of a Loan with a single conditional UpdateItem.
func (s *LoanStore) AddNote(ctx context.Context, k LoanKey, v LoanAddNote, opts ...dynago.WriteOption) error {
	key, err := k.dynamoKey()
	if err != nil {
		return err
	}
	o := dynago.ApplyOptions(opts)
	if v.Notes == nil {
		return nil // nothing to change
	}
	sets := []dynago.Set{}
	if v.Notes != nil {
		sets = append(sets, dynago.Set{Attr: "notes", Value: *v.Notes, Remove: *v.Notes == ""})
	}
	guard, err := s.guard(key, o, false)
	if err != nil {
		return err
	}
	return dynago.Retry(ctx, func() error {
		rev, err := dynago.UpdateFields(ctx, s.t, key, sets, nil, guard, nil)
		if err == nil {
			o.Written(rev)
		}
		return dynago.StaleAs(guard.ExpectRev != 0, err)
	})
}

// requireBorrowTool returns the writes Loan.Borrow makes to the Tool: it requires the Tool to exist
// with status = "available", and sets its status to "onLoan". Unless read is set, it assumes that
// state without reading the Tool: if the assumption is wrong, the transaction fails with
// dynago.ErrNeedsRead and the caller runs again with read set.
func (s *LoanStore) requireBorrowTool(ctx context.Context, e *Loan, read bool) ([]dynago.Op, dynago.Change, error) {
	k := ToolKey{LibraryID: e.LibraryID, ToolID: e.ToolID}
	key, err := k.dynamoKey()
	if err != nil {
		return nil, dynago.Change{}, err
	}
	if !read {
		before := Tool{LibraryID: k.LibraryID, ToolID: k.ToolID, Status: ToolStatusAvailable}
		after := before.clone()
		after.Status = ToolStatusOnLoan
		sets := []dynago.Set{
			{Attr: "status", Value: ToolStatusOnLoan},
		}
		u := s.t.Update("PK", key.PK).Range("SK", key.SK)
		dynago.SetFields(u, sets)
		dynago.GuardUpdate(u, dynago.Guard{Version: toolVersion}, dynago.Now())
		dynago.AtLeastVersion(u, 2)
		dynago.CondUpdate(u, dynago.Cond{Attr: "status", Value: ToolStatusAvailable, Zero: false})
		return []dynago.Op{dynago.UpdateOp(key, u, dynago.ErrNeedsRead)}, dynago.Change{Owner: key, Before: toolDerived(&before, key, toolVersion), After: toolDerived(&after, key, toolVersion)}, nil
	}
	it, err := (&ToolStore{db: s.db, t: s.t}).load(ctx, key, true)
	if err == ErrToolNotFound {
		return nil, dynago.Change{}, ErrLoanBorrowRequiresTool
	}
	if err != nil {
		return nil, dynago.Change{}, err
	}
	if it.V > toolVersion {
		return nil, dynago.Change{}, fmt.Errorf("%w: Tool at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, toolVersion)
	}
	before := &it.Tool
	if before.Status != ToolStatusAvailable {
		return nil, dynago.Change{}, ErrLoanBorrowRequiresTool
	}
	after := before.clone()
	after.Status = ToolStatusOnLoan
	return []dynago.Op{dynago.PutOp(key, s.t.Put(toolToItem(&after, key, it.Rev+1)).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", toolVersion), dynago.ErrStale)}, dynago.Change{Owner: key, Before: toolDerived(before, key, it.V), After: toolDerived(&after, key, toolVersion)}, nil
}

// requireBorrowHold returns the writes Loan.Borrow makes to the Hold: it requires any Hold to have
// memberId = Loan.memberId (an absent or expired one passes), and deletes the Hold if there is one.
// Unless read is set, it assumes that state without reading the Hold: if the assumption is wrong,
// the transaction fails with dynago.ErrNeedsRead and the caller runs again with read set.
func (s *LoanStore) requireBorrowHold(ctx context.Context, e *Loan, read bool) ([]dynago.Op, dynago.Change, error) {
	k := HoldKey{LibraryID: e.LibraryID, ToolID: e.ToolID}
	key, err := k.dynamoKey()
	if err != nil {
		return nil, dynago.Change{}, err
	}
	if !read {
		req := dynago.Requirement{Key: key, When: []dynago.Cond{{Attr: "memberId", Value: e.MemberID, Zero: e.MemberID == ""}}, TTLAttr: "ttl", Optional: true}
		return []dynago.Op{dynago.DeleteOp(key, dynago.ConsumeRequirement(s.t, req, holdVersion), dynago.ErrNeedsRead)}, dynago.Change{}, nil
	}
	it, err := (&HoldStore{db: s.db, t: s.t}).load(ctx, key, true)
	if err == ErrHoldNotFound {
		// Nothing to change, as long as one doesn't appear before the write commits.
		return []dynago.Op{dynago.CheckOp(key, dynago.CheckAbsent(s.t, key, "ttl"), dynago.ErrStale)}, dynago.Change{}, nil
	}
	if err != nil {
		return nil, dynago.Change{}, err
	}
	if it.V > holdVersion {
		return nil, dynago.Change{}, fmt.Errorf("%w: Hold at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, holdVersion)
	}
	before := &it.Hold
	if before.MemberID != e.MemberID {
		return nil, dynago.Change{}, ErrLoanBorrowRequiresHold
	}
	return []dynago.Op{dynago.DeleteOp(key, s.t.Delete("PK", key.PK).Range("SK", key.SK).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", holdVersion), dynago.ErrStale)}, dynago.Change{}, nil
}

// requireReturnTool returns the writes Loan.Return makes to the Tool: it requires the Tool to exist
// with status = "onLoan", and sets its status to "available". Unless read is set, it assumes that
// state without reading the Tool: if the assumption is wrong, the transaction fails with
// dynago.ErrNeedsRead and the caller runs again with read set.
func (s *LoanStore) requireReturnTool(ctx context.Context, e *Loan, read bool) ([]dynago.Op, dynago.Change, error) {
	k := ToolKey{LibraryID: e.LibraryID, ToolID: e.ToolID}
	key, err := k.dynamoKey()
	if err != nil {
		return nil, dynago.Change{}, err
	}
	if !read {
		before := Tool{LibraryID: k.LibraryID, ToolID: k.ToolID, Status: ToolStatusOnLoan}
		after := before.clone()
		after.Status = ToolStatusAvailable
		sets := []dynago.Set{
			{Attr: "status", Value: ToolStatusAvailable},
		}
		u := s.t.Update("PK", key.PK).Range("SK", key.SK)
		dynago.SetFields(u, sets)
		dynago.GuardUpdate(u, dynago.Guard{Version: toolVersion}, dynago.Now())
		dynago.AtLeastVersion(u, 2)
		dynago.CondUpdate(u, dynago.Cond{Attr: "status", Value: ToolStatusOnLoan, Zero: false})
		return []dynago.Op{dynago.UpdateOp(key, u, dynago.ErrNeedsRead)}, dynago.Change{Owner: key, Before: toolDerived(&before, key, toolVersion), After: toolDerived(&after, key, toolVersion)}, nil
	}
	it, err := (&ToolStore{db: s.db, t: s.t}).load(ctx, key, true)
	if err == ErrToolNotFound {
		return nil, dynago.Change{}, ErrLoanReturnRequiresTool
	}
	if err != nil {
		return nil, dynago.Change{}, err
	}
	if it.V > toolVersion {
		return nil, dynago.Change{}, fmt.Errorf("%w: Tool at v%d, this code is v%d", dynago.ErrNewerSchema, it.V, toolVersion)
	}
	before := &it.Tool
	if before.Status != ToolStatusOnLoan {
		return nil, dynago.Change{}, ErrLoanReturnRequiresTool
	}
	after := before.clone()
	after.Status = ToolStatusAvailable
	return []dynago.Op{dynago.PutOp(key, s.t.Put(toolToItem(&after, key, it.Rev+1)).If("$ = ? AND (attribute_not_exists($) OR $ <= ?)", "_rev", it.Rev, "_v", "_v", toolVersion), dynago.ErrStale)}, dynago.Change{Owner: key, Before: toolDerived(before, key, it.V), After: toolDerived(&after, key, toolVersion)}, nil
}

// ---- Hold ----

// Hold is a tool reserved for a member to collect, with a pickup code. While it is live, only that
// member can borrow the tool; borrowing collects it. Lapses after two days.
type Hold struct {
	LibraryID string `dynamo:"libraryId"`
	ToolID    string `dynamo:"toolId"`
	MemberID  string `dynamo:"memberId,omitempty"`
	// HMAC-SHA256 of the pickup code under a server-side secret, hex-encoded. Neither the code nor a
	// plain hash of it is stored: keys end up in backups and logs, and a short code's plain hash is
	// reversed by trying every code.
	CodeHash  string    `dynamo:"codeHash,omitempty"`
	CreatedAt time.Time `dynamo:"createdAt,omitempty"`
	// When the hold lapses. Required: a hold without one would reserve the tool forever.
	ExpiresAt time.Time `dynamo:"expiresAt,omitempty"`

	loaded *holdLoaded // set when the store returns the entity
}

// holdLoaded remembers the stored state an entity was read at, so a write passed the entity
// with dynago.From can start from it without reading again.
type holdLoaded struct {
	rev      int64
	v        int
	snapshot Hold
}

// Version identifies the stored state e was read at, for optimistic concurrency: pass it back
// with dynago.IfVersion (e.g. from an ETag) to make a write fail if anything changed since.
// It is "" for an entity that was not read from the store.
func (e *Hold) Version() string {
	if e.loaded == nil {
		return ""
	}
	return dynago.FormatVersion(e.loaded.rev)
}

// clone copies e, including its slices and maps, without its loaded state.
func (e *Hold) clone() Hold {
	c := *e
	c.loaded = nil
	return c
}

// checkKeyParts rejects values containing a character their key templates use as a separator.
func (e *Hold) checkKeyParts() error {
	if err := dynago.CheckKeyPart("libraryId", e.LibraryID, "#"); err != nil {
		return err
	}
	if err := dynago.CheckKeyPart("toolId", e.ToolID, "#"); err != nil {
		return err
	}
	return nil
}

// HoldKey identifies a Hold.
type HoldKey struct {
	LibraryID string
	ToolID    string
}

// Key returns the primary key of e.
func (e *Hold) Key() HoldKey {
	return HoldKey{LibraryID: e.LibraryID, ToolID: e.ToolID}
}

func (k HoldKey) dynamoKey() (dynago.Key, error) {
	if k.LibraryID == "" || k.ToolID == "" {
		return dynago.Key{}, fmt.Errorf("%w: Hold needs libraryId and toolId", dynago.ErrInvalidKey)
	}
	if err := dynago.CheckKeyPart("libraryId", k.LibraryID, "#"); err != nil {
		return dynago.Key{}, err
	}
	if err := dynago.CheckKeyPart("toolId", k.ToolID, "#"); err != nil {
		return dynago.Key{}, err
	}
	return dynago.Key{PK: "LIB#" + k.LibraryID + "#TOOL#" + k.ToolID, SK: "HOLD"}, nil
}

// Errors returned by HoldStore. Each wraps the matching dynago sentinel.
var (
	ErrHoldNotFound            = fmt.Errorf("%w: Hold", dynago.ErrNotFound)
	ErrHoldExists              = fmt.Errorf("%w: Hold", dynago.ErrExists)
	ErrHoldPlaceRequiresTool   = fmt.Errorf("%w: Hold.Place requires the Tool to exist with status = \"available\"", dynago.ErrPrecondition)
	ErrHoldPlaceRequiresMember = fmt.Errorf("%w: Hold.Place requires the Member to exist with status = \"active\"", dynago.ErrPrecondition)
)

const holdVersion = 1

type holdItem struct {
	Hold
	PK       string `dynamo:"PK"`
	SK       string `dynamo:"SK"`
	T        string `dynamo:"_t"`
	V        int    `dynamo:"_v"`
	Rev      int64  `dynamo:"_rev"`
	ByCodePK string `dynamo:"ByCodePK,omitempty"`
	TTL      int64  `dynamo:"ttl,omitempty"`
}

func holdToItem(e *Hold, key dynago.Key, rev int64) *holdItem {
	it := &holdItem{Hold: *e, PK: key.PK, SK: key.SK, T: "Hold", V: holdVersion, Rev: rev}
	if e.CodeHash != "" {
		it.ByCodePK = "HOLDCODE#" + e.CodeHash
	}
	it.TTL = dynago.UnixTTL(e.ExpiresAt)
	return it
}

// HoldByCode is a Hold as seen through the ByCode index: key fields plus the projected fields.
type HoldByCode struct {
	LibraryID string    `dynamo:"libraryId"`
	ToolID    string    `dynamo:"toolId"`
	MemberID  string    `dynamo:"memberId,omitempty"`
	CodeHash  string    `dynamo:"codeHash,omitempty"`
	ExpiresAt time.Time `dynamo:"expiresAt,omitempty"`
}

// HoldStore reads and writes Hold items. Only the access patterns declared in the schema
// exist as methods.
type HoldStore struct {
	db *dynamo.DB
	t  dynamo.Table
}

func (s *HoldStore) load(ctx context.Context, key dynago.Key, consistent bool) (*holdItem, error) {
	var raw dynamo.Item
	found, err := dynago.GetOne(ctx, s.t, key, consistent, &raw)
	if err != nil {
		return nil, err
	}
	if !found {
		return nil, ErrHoldNotFound
	}
	it, err := holdDecode(raw)
	if err != nil {
		return nil, err
	}
	// DynamoDB deletes expired items lazily, often hours later: treat them as gone.
	if dynago.Expired(it.TTL, dynago.Now()) {
		return nil, ErrHoldNotFound
	}
	return it, nil
}

// holdDecode decodes a stored item, remembering its state for writes passed dynago.From.
func holdDecode(raw dynamo.Item) (*holdItem, error) {
	var it holdItem
	if err := dynamo.UnmarshalItem(raw, &it); err != nil {
		return nil, err
	}
	it.loaded = &holdLoaded{rev: it.Rev, v: it.V, snapshot: it.clone()}
	return &it, nil
}

func holdDecodeAll(raws []dynamo.Item) ([]Hold, error) {
	out := make([]Hold, 0, len(raws))
	for _, raw := range raws {
		it, err := holdDecode(raw)
		if err != nil {
			return nil, err
		}
		out = append(out, it.Hold)
	}
	return out, nil
}

// from returns the entity passed with dynago.From, checked to be this item and read from the
// store, or nil if none was passed.
func (s *HoldStore) from(key dynago.Key, o dynago.WriteOptions) (*Hold, error) {
	if o.From == nil {
		return nil, nil
	}
	from, ok := o.From.(*Hold)
	if !ok || from == nil || from.loaded == nil {
		return nil, fmt.Errorf("%w: dynago.From needs a *Hold read from its own item, not built by hand or read through a copy index", dynago.ErrVersionRequired)
	}
	if fk, err := from.Key().dynamoKey(); err != nil || fk != key {
		return nil, fmt.Errorf("%w: the Hold passed with dynago.From is a different item", dynago.ErrInvalidKey)
	}
	return from, nil
}

// guard resolves the conditions a single-request write must meet.
func (s *HoldStore) guard(key dynago.Key, o dynago.WriteOptions, required bool) (dynago.Guard, error) {
	expect, err := o.ExpectedRev()
	if err != nil {
		return dynago.Guard{}, err
	}
	from, err := s.from(key, o)
	if err != nil {
		return dynago.Guard{}, err
	}
	if from != nil {
		if expect != 0 && expect != from.loaded.rev {
			return dynago.Guard{}, dynago.ErrVersionMismatch
		}
		expect = from.loaded.rev
	}
	if required && expect == 0 {
		return dynago.Guard{}, dynago.ErrVersionRequired
	}
	return dynago.Guard{ExpectRev: expect, Version: holdVersion, TTLAttr: "ttl", NotFound: ErrHoldNotFound}, nil
}

// Get reads a Hold by primary key with one eventually consistent GetItem.
func (s *HoldStore) Get(ctx context.Context, k HoldKey) (*Hold, error) {
	key, err := k.dynamoKey()
	if err != nil {
		return nil, err
	}
	it, err := s.load(ctx, key, false)
	if err != nil {
		return nil, err
	}
	return &it.Hold, nil
}

// HoldFindByCodeQuery selects the partition for Hold.FindByCode.
type HoldFindByCodeQuery struct {
	CodeHash string
}

// FindByCode returns one page of Hold items from the ByCode index, ascending by "", with exactly
// one eventually consistent Query (default 1, max 1 items). It returns the cursor for the next
// page, or "" at the end.
func (s *HoldStore) FindByCode(ctx context.Context, q HoldFindByCodeQuery, page dynago.Page) ([]HoldByCode, string, error) {
	if q.CodeHash == "" {
		return nil, "", fmt.Errorf("%w: FindByCode needs codeHash", dynago.ErrInvalidKey)
	}
	pk := "HOLDCODE#" + q.CodeHash
	spec := dynago.QuerySpec{Scope: "Hold.FindByCode@v1\x00" + pk, PK: pk, PageSize: 1, MaxPage: 1, Index: "ByCode", PKAttr: "ByCodePK", TTLAttr: "ttl"}
	var out []HoldByCode
	next, err := dynago.Query(ctx, s.t, spec, page, &out)
	if err != nil {
		return nil, "", err
	}
	return out, next, nil
}

// Place creates a Hold, failing with ErrHoldExists if one already exists (an expired one is
// replaced). MemberId, codeHash and expiresAt must be set (else dynago.ErrFieldRequired). In the
// same transaction it requires the Tool to exist with status = "available" (else
// ErrHoldPlaceRequiresTool); the Member to exist with status = "active" (else
// ErrHoldPlaceRequiresMember). Afterwards e.Version() returns the new item's version.
func (s *HoldStore) Place(ctx context.Context, e *Hold) error {
	key, err := e.Key().dynamoKey()
	if err != nil {
		return err
	}
	if e.MemberID == "" {
		err := fmt.Errorf("%w: Hold.memberId", dynago.ErrFieldRequired)
		return err
	}
	if e.CodeHash == "" {
		err := fmt.Errorf("%w: Hold.codeHash", dynago.ErrFieldRequired)
		return err
	}
	if e.ExpiresAt.IsZero() {
		err := fmt.Errorf("%w: Hold.expiresAt", dynago.ErrFieldRequired)
		return err
	}
	if err := e.checkKeyParts(); err != nil {
		return err
	}
	rev := dynago.NewRev()
	return dynago.Retry(ctx, func() error {
		put := s.t.Put(holdToItem(e, key, rev)).If("attribute_not_exists($) OR $ <= ?", "PK", "ttl", dynago.Now())
		ops := []dynago.Op{dynago.CreateOp(key, put, ErrHoldExists, rev)}
		// requires Tool
		if e.LibraryID == "" || e.ToolID == "" {
			return fmt.Errorf("%w: Hold.Place requires the Tool, keyed by libraryId and toolId", dynago.ErrFieldRequired)
		}
		toolKey := dynago.Key{PK: "LIB#" + e.LibraryID + "#TOOL#" + e.ToolID, SK: "TOOL"}
		ops = append(ops, dynago.CheckOp(toolKey, dynago.CheckRequirement(s.t, dynago.Requirement{Key: toolKey, When: []dynago.Cond{{Attr: "status", Value: ToolStatusAvailable, Zero: false}}}), ErrHoldPlaceRequiresTool))
		// requires Member
		if e.LibraryID == "" || e.MemberID == "" {
			return fmt.Errorf("%w: Hold.Place requires the Member, keyed by libraryId and memberId", dynago.ErrFieldRequired)
		}
		memberKey := dynago.Key{PK: "LIB#" + e.LibraryID, SK: "MEMBER#" + e.MemberID}
		ops = append(ops, dynago.CheckOp(memberKey, dynago.CheckRequirement(s.t, dynago.Requirement{Key: memberKey, When: []dynago.Cond{{Attr: "status", Value: MemberStatusActive, Zero: false}}}), ErrHoldPlaceRequiresMember))
		if err := dynago.Run(ctx, s.db, ops); err != nil {
			return err
		}
		e.loaded = &holdLoaded{rev: rev, v: holdVersion, snapshot: e.clone()}
		return nil
	})
}

// Release deletes a Hold with one conditional DeleteItem, failing with ErrHoldNotFound if it is
// absent.
func (s *HoldStore) Release(ctx context.Context, k HoldKey, opts ...dynago.WriteOption) error {
	key, err := k.dynamoKey()
	if err != nil {
		return err
	}
	guard, err := s.guard(key, dynago.ApplyOptions(opts), false)
	if err != nil {
		return err
	}
	return dynago.Retry(ctx, func() error {
		return dynago.StaleAs(guard.ExpectRev != 0, dynago.DeleteIfExists(ctx, s.t, key, guard))
	})
}
